with src_c as (
  select * from jsonb_to_recordset($seed$[{"name":"Pixel Forge Digital","size":"11-50","location":"Remote","website":"https://pixelforgedigital.example.com","description":"Pixel Forge Digital is a distributed web engineering agency crafting high-converting marketing sites, custom storefronts, and bespoke web apps for startups and consumer brands across Europe and MENA. Our 28 engineers, designers, and strategists work asynchronously with clear weekly client demos."},{"name":"Nimbus Cloud","size":"201-1000","location":"Toronto, Canada","website":"https://nimbuscloud.example.com","description":"Nimbus Cloud builds cloud invoicing, automated payroll, and cash-flow software trusted by over 65,000 small businesses across North America. Headquartered in Toronto with remote product squads, we obsess over speed, auditability, and calm financial workflows."},{"name":"Skyline Telecom","size":"1000+","location":"Amman, Jordan","website":"https://skylinetelecom.example.com","description":"Skyline Telecom operates nationwide 4G/5G mobile networks, FTTH fiber broadband, and enterprise cloud connectivity for over 3.2 million subscribers in Jordan. Our engineering and digital teams modernize both physical radio/fiber infrastructure and self-service customer apps."},{"name":"Aurora Medical Center","size":"1000+","location":"Dubai, UAE","website":"https://auroramedical.example.com","description":"Aurora Medical Center is a 400-bed JCI-accredited teaching hospital and multi-specialty outpatient network in Dubai serving over 450,000 patient visits annually. We combine academic clinical rigor, subspecialty surgery, and modern diagnostic imaging under one campus."},{"name":"Cedarcrest Hospital","size":"1000+","location":"Beirut, Lebanon","website":"https://cedarcresthospital.example.com","description":"Cedarcrest Hospital is a 350-bed university teaching hospital in Beirut recognized regionally for tertiary cardiology, critical care, emergency medicine, and clinical residency training. Over 1,200 physicians, nurses, and allied health professionals deliver evidence-based inpatient and outpatient care."},{"name":"Summit Bank","size":"1000+","location":"London, UK","website":"https://summitbank.example.com","description":"Summit Bank is a UK retail, SME, and commercial bank serving 1.4 million personal and business customers through modern digital channels and regional relationship hubs. Our London teams balance prudent credit underwriting with fast, transparent business lending."},{"name":"Levant Commercial Bank","size":"1000+","location":"Beirut, Lebanon","website":"https://levantbank.example.com","description":"Levant Commercial Bank is an established commercial and retail bank operating 40 branches alongside a rapidly growing mobile banking and merchant treasury platform. We focus on transparent customer service, rigorous AML governance, and SME trade financing."},{"name":"Gulfstream Capital","size":"51-200","location":"Dubai, UAE","website":"https://gulfstreamcapital.example.com","description":"Gulfstream Capital is a DIFC-regulated asset management firm overseeing $3.8B across MENA public equities, sovereign/corporate fixed income, and quantitative multi-asset strategies for institutional and family-office clients."},{"name":"Horizon Policy Institute","size":"51-200","location":"Geneva, Switzerland","website":"https://horizonpolicy.example.com","description":"Horizon Policy Institute is an independent economic and public-policy research institute in Geneva studying international trade, labor markets, climate transitions, and emerging-market fiscal resilience. Our economists publish peer-reviewed papers and advise multilateral agencies and ministries."},{"name":"Helix Biolabs","size":"201-1000","location":"Boston, USA","website":"https://helixbiolabs.example.com","description":"Helix Biolabs develops molecular diagnostic assays, NGS sequencing panels, and automated laboratory instruments for inherited and rare genetic conditions. Operating CLIA-certified and GMP-compliant facilities in Cambridge/Boston, we bridge bench science with clinical care."},{"name":"Terra Labs","size":"51-200","location":"Amsterdam, Netherlands","website":"https://terralabs.example.com","description":"Terra Labs provides accredited environmental monitoring—sampling air quality, municipal water, industrial soils, and food-chain microbiology for European cities and manufacturers. Our Amsterdam scientists pair field testing with predictive GIS and pollution-forecasting models."},{"name":"Delta Process Engineering","size":"201-1000","location":"Abu Dhabi, UAE","website":"https://deltaprocess.example.com","description":"Delta Process Engineering delivers EPC process design, safety engineering, instrumentation, and plant optimization for energy, petrochemicals, and industrial utilities across Abu Dhabi and the wider GCC. Our multidisciplinary engineers support brownfield revamps and greenfield modular skids."},{"name":"Lawson & Reed","size":"51-200","location":"London, UK","website":"https://lawsonreed.example.com","description":"Lawson & Reed is a mid-market City of London law firm advising technology, finance, and industrial clients on M&A transactions, commercial contracts, regulatory compliance, and commercial disputes with partner-led teams."},{"name":"Peopleworks","size":"11-50","location":"Cairo, Egypt","website":"https://peopleworks.example.com","description":"Peopleworks is an HR advisory, technical recruiting, and organizational learning partner helping high-growth tech and commercial companies across Egypt and MENA build healthy, high-performing teams."},{"name":"Bluewave Hotels","size":"1000+","location":"Dubai, UAE","website":"https://bluewavehotels.example.com","description":"Bluewave Hotels operates 14 beachfront resorts and urban lifestyle hotels across the UAE, Oman, and Bahrain. Known for warm service and vibrant dining concepts, we employ over 2,400 hospitality professionals across rooms, culinary, revenue, and guest experience."},{"name":"Swiftline Logistics","size":"201-1000","location":"Rotterdam, Netherlands","website":"https://swiftlinelogistics.example.com","description":"Swiftline Logistics orchestrates ocean, road, and air freight forwarding plus bonded warehouse fulfillment out of Rotterdam for European retail and industrial manufacturers. Our operations and analytics teams manage customs clearance and real-time multimodal tracking."},{"name":"Daily Ledger Media","size":"51-200","location":"Beirut, Lebanon","website":"https://dailyledgermedia.example.com","description":"Daily Ledger Media publishes an independent bilingual Arabic–English business and current-affairs news site alongside a flagship weekly investigative video show. From our Beirut newsroom, 65 journalists, video producers, translators, and web engineers serve over 1.8 million monthly readers."}]$seed$::jsonb) as x(name text, size text, location text, website text, description text)
