upd_c as (
  update public.companies c
  set
    size = s.size::public.company_size,
    location = s.location,
    website = s.website,
    description = s.description
  from src_c s
  where c.is_demo and c.name = s.name
  returning c.id, c.name
),
ins_c as (
  insert into public.companies (name, size, location, website, description, is_demo)
  select s.name, s.size::public.company_size, s.location, s.website, s.description, true
  from src_c s
  where not exists (select 1 from public.companies c where c.is_demo and c.name = s.name)
  returning id, name
),
all_c as (
  select id, name from public.companies where is_demo
  union
  select id, name from ins_c
),
src_j as (
  select * from jsonb_to_recordset($seed$[{"company":"Pixel Forge Digital","title":"Next.js Developer","description":"Pixel Forge Digital is a distributed web engineering agency crafting high-converting marketing sites, custom storefronts, and bespoke web apps for startups and consumer brands across Europe and MENA. Our 28 engineers, designers, and strategists work asynchronously with clear weekly client demos. We're hiring a Next.js Developer to join the team (remote).\n\nAbout the role:\nJoin a 4-person client delivery pod building high-speed marketing platforms, SaaS dashboards, and headless storefronts in Next.js App Router and Vercel.\n\nWhat you'll do:\n- Architect and ship SSR/ISR marketing sites and interactive web apps using Next.js App Router, React, and TypeScript.\n- Collaborate with Pixel Forge designers to craft smooth, accessible micro-interactions without sacrificing Core Web Vitals.\n- Integrate headless CMS platforms (Sanity, Contentful, Strapi) with live preview and on-demand revalidation webhooks.\n- Hit Lighthouse Performance, SEO, and Accessibility scores of 90+ across desktop and mobile viewports.\n- Communicate progress clearly in async client Slack channels and weekly live demos.\n\nRequirements:\n- 2+ years of production experience shipping Next.js and TypeScript web applications.\n- Strong command of Tailwind CSS, semantic HTML, technical SEO metadata, and image/font optimization.\n- Hands-on experience deploying and debugging apps on Vercel (Edge/Node runtimes, caching, ISR).\n- Clean Git workflow and comfort interfacing directly with designers and non-technical clients.\n\nNice to have:\n- Experience with Framer Motion, GSAP ScrollTrigger, or headless Shopify Storefront API.\n- Portfolio of 2–3 live production websites you built.\n\nCompensation & benefits:\n- Monthly salary: $2,000–$3,300 USD / month (Full-time, Remote)\n- 100% remote work with flexible hours and a $1,000 laptop/setup budget\n- 24 days paid annual leave plus national holidays\n- Annual $1,000 training, certification, and conference allowance\n- Profit-sharing year-end bonus based on delivery quality\n\nHiring process:\n- 1. 25-minute intro call covering background, role scope, and monthly compensation alignment\n- 2. Practical role exercise (portfolio walkthrough or real-world technical pairing — no trick whiteboard puzzles)\n- 3. Final conversation with the hiring manager and cross-functional peers","field":"Software","seniority":"mid","type":"full_time","mode":"remote","location":"Remote","skills":["Next.js","React","TypeScript","Tailwind CSS","Vercel","Git"],"reqs":["2+ years of production experience shipping Next.js and TypeScript web applications.","Strong command of Tailwind CSS, semantic HTML, technical SEO metadata, and image/font optimization.","Hands-on experience deploying and debugging apps on Vercel (Edge/Node runtimes, caching, ISR).","Clean Git workflow and comfort interfacing directly with designers and non-technical clients."],"lo":2000,"hi":3300,"days":2,"hours":6},{"company":"Pixel Forge Digital","title":"Junior Web Developer","description":"Pixel Forge Digital is a distributed web engineering agency crafting high-converting marketing sites, custom storefronts, and bespoke web apps for startups and consumer brands across Europe and MENA. Our 28 engineers, designers, and strategists work asynchronously with clear weekly client demos. We're hiring a Junior Web Developer to join the team (remote).\n\nAbout the role:\nStart your agency engineering career turning crisp Figma designs into pixel-accurate responsive web pages while learning modern Next.js and TypeScript through daily code reviews.\n\nWhat you'll do:\n- Build responsive multi-breakpoint pages and reusable UI sections from Figma designs using HTML, Tailwind CSS, and React.\n- Audit and fix cross-browser layout bugs across Safari, Chrome, and mobile devices.\n- Wire up forms, CMS content blocks, and basic interactive states cleanly.\n- Participate in pull-request reviews and gradually take on Next.js App Router tickets alongside senior engineers.\n\nRequirements:\n- A portfolio of 2–3 live, responsive websites or web apps you built yourself (with source code on GitHub).\n- Strong fundamentals in modern CSS (Flexbox, Grid, clamp/responsive spacing), semantic HTML, and JavaScript (ES6+).\n- Working familiarity with React components, props/state, and Git basics.\n- Reliable remote communication habits and eagerness to learn through feedback.\n\nNice to have:\n- Basic experience with TypeScript, Tailwind CSS, or Next.js.\n- Eye for typography, whitespace, and subtle CSS transitions.\n\nCompensation & benefits:\n- Monthly salary: $1,100–$1,800 USD / month (Full-time, Remote)\n- 100% remote work with flexible hours and a $1,000 laptop/setup budget\n- 24 days paid annual leave plus national holidays\n- Annual $1,000 training, certification, and conference allowance\n- Profit-sharing year-end bonus based on delivery quality\n\nHiring process:\n- 1. 25-minute intro call covering background, role scope, and monthly compensation alignment\n- 2. Practical role exercise (portfolio walkthrough or real-world technical pairing — no trick whiteboard puzzles)\n- 3. Final conversation with the hiring manager and cross-functional peers","field":"Software","seniority":"junior","type":"full_time","mode":"remote","location":"Remote","skills":["HTML","CSS","JavaScript","React","Git","Responsive Design"],"reqs":["A portfolio of 2–3 live, responsive websites or web apps you built yourself (with source code on GitHub).","Strong fundamentals in modern CSS (Flexbox, Grid, clamp/responsive spacing), semantic HTML, and JavaScript (ES6+).","Working familiarity with React components, props/state, and Git basics.","Reliable remote communication habits and eagerness to learn through feedback."],"lo":1100,"hi":1800,"days":9,"hours":11},{"company":"Pixel Forge Digital","title":"WordPress Developer","description":"Pixel Forge Digital is a distributed web engineering agency crafting high-converting marketing sites, custom storefronts, and bespoke web apps for startups and consumer brands across Europe and MENA. Our 28 engineers, designers, and strategists work asynchronously with clear weekly client demos. We're hiring a WordPress Developer to join the team (remote).\n\nAbout the role:\nOwn custom Gutenberg block themes, legacy-to-modern WordPress migrations, and speed/security hardening across Pixel Forge's editorial and B2B agency retainers.\n\nWhat you'll do:\n- Develop clean, custom WordPress themes and ACF/Gutenberg blocks from scratch without bloated page builders.\n- Migrate legacy sites cleanly—preserving URL redirects, SEO metadata, media libraries, and MySQL integrity.\n- Diagnose slow database queries, optimize asset loading, and configure page/object caching for 90+ mobile speed.\n- Manage plugin/core security updates, staging deploys, and WooCommerce customizations where needed.\n\nRequirements:\n- 3+ years building custom WordPress themes and plugins with modern PHP, JavaScript, CSS, and MySQL.\n- Strong command of WordPress block editor (Gutenberg) or ACF Pro block architecture.\n- Proven track record tuning WordPress Core Web Vitals and securing production sites.\n- Ability to scope and deliver remote contract milestones independently.\n\nNice to have:\n- Experience with Roots/Sage, Bedrock, or headless WordPress + Next.js.\n- Familiarity with WP-CLI and Cloudflare CDN/WAF rules.\n\nCompensation & benefits:\n- Monthly salary: $2,000–$3,300 USD / month (Contract, Remote)\n- 100% remote work with flexible hours and a $1,000 laptop/setup budget\n- 24 days paid annual leave plus national holidays\n- Annual $1,000 training, certification, and conference allowance\n- Profit-sharing year-end bonus based on delivery quality\n\nHiring process:\n- 1. 25-minute intro call covering background, role scope, and monthly compensation alignment\n- 2. Practical role exercise (portfolio walkthrough or real-world technical pairing — no trick whiteboard puzzles)\n- 3. Final conversation with the hiring manager and cross-functional peers","field":"Software","seniority":"mid","type":"contract","mode":"remote","location":"Remote","skills":["WordPress","PHP","JavaScript","CSS","MySQL"],"reqs":["3+ years building custom WordPress themes and plugins with modern PHP, JavaScript, CSS, and MySQL.","Strong command of WordPress block editor (Gutenberg) or ACF Pro block architecture.","Proven track record tuning WordPress Core Web Vitals and securing production sites.","Ability to scope and deliver remote contract milestones independently."],"lo":2000,"hi":3300,"days":16,"hours":16},{"company":"Pixel Forge Digital","title":"Shopify Developer","description":"Pixel Forge Digital is a distributed web engineering agency crafting high-converting marketing sites, custom storefronts, and bespoke web apps for startups and consumer brands across Europe and MENA. Our 28 engineers, designers, and strategists work asynchronously with clear weekly client demos. We're hiring a Shopify Developer to join the team (remote).\n\nAbout the role:\nBuild high-converting Online Store 2.0 themes, custom bundle builders, and clean third-party app integrations for consumer brands scaling on Shopify.\n\nWhat you'll do:\n- Customize and extend Shopify Online Store 2.0 themes using Liquid, modern JavaScript, and clean CSS.\n- Build bespoke product configurators, slide-out cart drawers, upsell modules, and metafield-driven sections.\n- Integrate ERP/fulfillment apps, regional payment methods, and analytics pixels cleanly without script bloat.\n- Optimize storefront load speed, mobile checkout UX, and accessibility across devices.\n\nRequirements:\n- 2+ years developing custom Shopify themes and storefront features.\n- Live examples of 2+ Shopify stores you built or heavily customized.\n- Deep command of Liquid, Shopify sections/metafields, AJAX Cart API, and responsive CSS.\n- Strong grasp of e-commerce conversion UX and storefront performance tuning.\n\nNice to have:\n- Experience with Shopify Functions, Hydrogen/Oxygen, or Checkout UI Extensions.\n- Experience localizing multi-currency / bilingual RTL storefronts.\n\nCompensation & benefits:\n- Monthly salary: $2,000–$3,300 USD / month (Contract, Remote)\n- 100% remote work with flexible hours and a $1,000 laptop/setup budget\n- 24 days paid annual leave plus national holidays\n- Annual $1,000 training, certification, and conference allowance\n- Profit-sharing year-end bonus based on delivery quality\n\nHiring process:\n- 1. 25-minute intro call covering background, role scope, and monthly compensation alignment\n- 2. Practical role exercise (portfolio walkthrough or real-world technical pairing — no trick whiteboard puzzles)\n- 3. Final conversation with the hiring manager and cross-functional peers","field":"Software","seniority":"mid","type":"contract","mode":"remote","location":"Remote","skills":["Shopify","Liquid","JavaScript","CSS","E-commerce"],"reqs":["2+ years developing custom Shopify themes and storefront features.","Live examples of 2+ Shopify stores you built or heavily customized.","Deep command of Liquid, Shopify sections/metafields, AJAX Cart API, and responsive CSS.","Strong grasp of e-commerce conversion UX and storefront performance tuning."],"lo":2000,"hi":3300,"days":2,"hours":21},{"company":"Pixel Forge Digital","title":"Laravel Developer","description":"Pixel Forge Digital is a distributed web engineering agency crafting high-converting marketing sites, custom storefronts, and bespoke web apps for startups and consumer brands across Europe and MENA. Our 28 engineers, designers, and strategists work asynchronously with clear weekly client demos. We're hiring a Laravel Developer to join the team (remote).\n\nAbout the role:\nBuild custom booking portals, client CRMs, and API backends in Laravel for European service businesses outgrowing off-the-shelf spreadsheets.\n\nWhat you'll do:\n- Design and implement maintainable Laravel applications, REST APIs, queued jobs, and webhook listeners.\n- Model normalized MySQL schemas, write efficient Eloquent queries, and guard against N+1 regressions.\n- Build clean interactive admin and customer portal screens using Vue.js or Inertia.js.\n- Write thorough Pest/PHPUnit feature tests for business rules, permissions, and billing logic.\n- Maintain zero-downtime deployment pipelines with Laravel Forge / GitHub Actions.\n\nRequirements:\n- 3+ years of production PHP and Laravel development experience.\n- Strong MySQL design, REST API architecture, and automated testing (PHPUnit/Pest) habits.\n- Working experience with Vue.js, Inertia, or Livewire for full-stack delivery.\n- Clear written English for async remote team collaboration.\n\nNice to have:\n- Experience with Laravel Horizon, Cashier/Stripe, or multi-tenant SaaS patterns.\n- Docker local/CI workflow experience.\n\nCompensation & benefits:\n- Monthly salary: $2,000–$3,300 USD / month (Full-time, Remote)\n- 100% remote work with flexible hours and a $1,000 laptop/setup budget\n- 24 days paid annual leave plus national holidays\n- Annual $1,000 training, certification, and conference allowance\n- Profit-sharing year-end bonus based on delivery quality\n\nHiring process:\n- 1. 25-minute intro call covering background, role scope, and monthly compensation alignment\n- 2. Practical role exercise (portfolio walkthrough or real-world technical pairing — no trick whiteboard puzzles)\n- 3. Final conversation with the hiring manager and cross-functional peers","field":"Software","seniority":"mid","type":"full_time","mode":"remote","location":"Remote","skills":["PHP","Laravel","MySQL","Vue","REST APIs"],"reqs":["3+ years of production PHP and Laravel development experience.","Strong MySQL design, REST API architecture, and automated testing (PHPUnit/Pest) habits.","Working experience with Vue.js, Inertia, or Livewire for full-stack delivery.","Clear written English for async remote team colla